class Shape {
  final int x;
  final int y;
  final String label;

  Shape(this.x, this.y, {required this.label});

  int area() {
    return this.x * this.y;
  }
}

class Square extends Shape {
  final int border;

  Square(super.x, super.y, this.border, {required super.label});

  int framed() {
    return this.area() + this.border;
  }
}

class Tall extends Square {
  Tall(super.x, super.border, {required super.label}) ;
}

int run() {
  var s = Square(3, 4, 10, label: 'sq');
  return s.framed();
}

String describe() {
  var s = Square(2, 2, 1, label: 'small');
  return '${s.label}:${s.x}x${s.y}';
}
